const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const antakya = ee.Geometry.Point([36.2676, 36.2023]); // Approximate center of Antakya

  const baselineStartDate = '2023-01-01';
  const baselineEndDate = '2023-01-31'; // January 2023 as baseline before earthquake

  const event1Date = '2023-02-21';
  const event2Date = '2023-04-30';

  const scale = 500; // VIIRS native resolution is ~750m, 500m is fine.

  // 2. Data Acquisition
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG/2023')
    .filterBounds(antakya)
    .select('avg_rad'); // Select the average radiance band

  // Function to get image and check collection size
  const getImage = (collection, date, name) => {
    const imgCol = collection.filterDate(date, ee.Date(date).advance(1, 'day'));
    const size = imgCol.size().getInfo();
    if (size === 0) {
      throw new Error(`C1: No images found for ${name} (${date}).`);
    }
    return imgCol.mean(); // Take the mean if multiple images exist for a single day, though usually one for daily composites.
  };

  let baselineImage, event1Image, event2Image;
  try {
    const baselineCol = viirsCollection.filterDate(baselineStartDate, baselineEndDate);
    if (baselineCol.size().getInfo() === 0) {
      throw new Error('C1: No images found for baseline period.');
    }
    baselineImage = baselineCol.mean();

    event1Image = getImage(viirsCollection, event1Date, 'Feb 21');
    event2Image = getImage(viirsCollection, event2Date, 'Apr 30');

  } catch (e) {
    console.log(e.message);
    console.log("C1");
    return;
  }

  // 3. Processing and Pixel Count Check (C2)
  const getMeanRadiance = async (image, name) => {
    const region = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: antakya,
      scale: scale,
      maxPixels: 1e9
    });

    const countRegion = image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: antakya,
      scale: scale,
      maxPixels: 1e9
    });

    const radiance = region.get('avg_rad').getInfo();
    const pixelCount = countRegion.get('avg_rad').getInfo();

    if (pixelCount === 0) {
      throw new Error(`C2: No valid pixels found for ${name} after processing.`);
    }
    if (radiance === null || radiance === undefined || isNaN(radiance)) {
      throw new Error(`C3: Radiance calculation failed for ${name}.`);
    }
    console.log(`${name} Radiance: ${radiance.toFixed(4)}, Valid Pixels: ${pixelCount}`);
    return radiance;
  };

  let baselineRadiance, event1Radiance, event2Radiance;
  try {
    baselineRadiance = await getMeanRadiance(baselineImage, 'Baseline (Jan)');
    event1Radiance = await getMeanRadiance(event1Image, 'Feb 21');
    event2Radiance = await getMeanRadiance(event2Image, 'Apr 30');
  } catch (e) {
    console.log(e.message);
    if (e.message.includes('C2')) {
      console.log("C2");
    } else {
      console.log("C3");
    }
    return;
  }

  // 4. Calculation of Increase
  const increaseFeb21 = event1Radiance - baselineRadiance;
  const increaseApr30 = event2Radiance - baselineRadiance;

  if (increaseFeb21 === null || increaseFeb21 === undefined || isNaN(increaseFeb21) ||
      increaseApr30 === null || increaseApr30 === undefined || isNaN(increaseApr30)) {
    console.log("C3: Increase calculation failed (null/NaN result).");
    return;
  }

  console.log(`Increase Feb 21 vs Baseline: ${increaseFeb21.toFixed(4)} nW/cm²/sr`);
  console.log(`Increase Apr 30 vs Baseline: ${increaseApr30.toFixed(4)} nW/cm²/sr`);

  // 5. Validation & Final Answer
  if (increaseFeb21 > increaseApr30) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
